+                                                        : revisionRepository
+                                                                .findById(event.revisionId())
+                                                                .map(ArticleRevision::revisionNo)
+                                                                .orElse(null),
+                                                event.actorUserId(),
+                                                event.occurredAt()))
+                        .orElse(null);
+        return new AdminArticleSummaryResult(
+                article.articleId().value(),
+                article.title(),
+                article.readingOrder(),
