+     */
+    private static Boolean needsUpdate(
+            ExampleAllocation example, Optional<Set<String>> openSectorCodes) {
+        if (openSectorCodes.isEmpty()) {
+            return null;
+        }
+        if (example == null) {
+            return Boolean.TRUE;
+        }
